import { Component, Element, h, Host, Prop, State, type ComponentInterface } from '@stencil/core';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { Consume } from '@src/framework/runtime-context';
import { SideNavigationContext } from './context';
import { Slot, Slots } from '@src/framework/decorators';

const prefix = 'nav-item';

/**
 * @slot prefix - Slot for content to be placed before the main nav item text, typically an icon.
 * @slot suffix - Slot for content to be placed after the main nav item text.
 * @slot default - Slot for the main nav item label content.
 * @part base - The base container of the component.
 */
@Component({
  styleUrl: 'styles/ks-nav-item.scss',
  tag: 'ks-nav-item',
  shadow: true,
})
export class KsNavItem implements ComponentInterface {
  @Element() el!: HTMLKsNavItemElement;

  @Consume({
    context: SideNavigationContext,
    subscribe: true,
    path: ['active'],
  })
  @State()
  activeValue?: string;

  @Consume({
    context: SideNavigationContext,
    path: ['onActivate'],
  })
  private onActivate?: (value: string) => void;

  /** Whether the nav item is disabled. */
  @Prop() disabled = false;
  /** The value of current nav item. */
  @Prop() value!: string;
  /** Whether the nav item is active. */
  @Prop() active?: boolean;
  /** Level of the nav item in the navigation tree. */
  @Prop() level = 0;
  /** The size of the nav item */
  @Prop() size: 'sm' | 'md' = 'sm';
  /** Whether the nav item is collapsed. */
  @Prop() collapsed = false;

  @Slot({ slotname: 'prefix' }) private prefixSlots?: Slots;

  constructor() {
    registerPluginManager(this.el);
  }

  private handleClick = () => {
    if (this.disabled) return;

    this.onActivate?.(this.value);

    sendActionTracking(this.el, { eventType: 'click', componentParams: { value: this.el } });
  };

  render() {
    const { disabled } = this;
    // eslint-disable-next-line no-autofix/@typescript-eslint/no-unnecessary-condition
    const mergedActive = this.active === undefined ? this.activeValue === this.value : this.active;

    return (
      <Host class="KsNavItem">
        <div
          class={{
            [prefix]: true,
            [`${prefix}--${this.size}`]: true,
            [`${prefix}--root`]: this.level < 1,
            [`${prefix}--collapsed`]: this.collapsed,
            [`${prefix}--active`]: mergedActive,
            [`${prefix}--disabled`]: disabled,
          }}
          style={{ '--ks-comp-side-navigation-level': `${this.level}` }}
          onClick={this.handleClick}
          part="base"
          data-testid="ks-nav-item-index-3Vpe2J"
        >
          {this.prefixSlots && (
            <div class={`${prefix}__prefix--wrapper`}>
              <slot name="prefix" />
            </div>
          )}

          <div class={`${prefix}__content`}>
            <slot />
          </div>

          <slot name="suffix" />
        </div>
      </Host>
    );
  }
}
